func atomic_notify[T uint32 | uint64](mem []byte, addr T, count int32, waiters *sync.Map) int32 {
	_ = atomic_ptr32(mem, addr)

	if waiters == nil {
		return 0
	}
	wa, ok := waiters.Load(int64(addr))
	if !ok {
		return 0
	}

	w := wa.(*atomic_waiters)
	w.Lock()

	var res uint32
	for res < uint32(count) && w.N > 0 {
		w.C <- struct{}{}
		w.N--
		res++
	}

	w.Unlock()
	return int32(res)
}

